def experiment(inputs):
    import random
    def sort_recursive(data, depth):
        if len(data) <= 1:
            return data, depth
        mid = len(data) // 2
        left, left_d = sort_recursive(data[:mid], depth + 1)
        right, right_d = sort_recursive(data[mid:], depth + 1)
        merged = sorted(left + right)
        return merged, max(left_d, right_d)
    trials = inputs.get('trials', [])
    results = []
    for t in trials:
        res, final_depth = sort_recursive(t, 0)
        results.append({'sorted': res, 'depth': final_depth, 'correct': res == sorted(t)})
    return {'results': results}

